def find_unique_counter_examples(S):
    counter_examples = set()
    for i in range(len(S)):
        for j in range(len(S)):
            x = S[i]
            y = S[j]
            if x * y != y * x:
                counter_examples.add(x)
                counter_examples.add(y)
    return sorted(counter_examples)

# Example set S
S = [1, 2, 3, 4, 5]
unique_elements = find_unique_counter_examples(S)
print(unique_elements)
